-- Farmplast: retire Cloud telemetry after all five NJ assets moved to MSI RAM.
-- Preserve Payroll, HR, ZKT, Auth, photos, PA climate and their full schema.
-- No CASCADE and no writes to protected business tables.
BEGIN;
SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
SET LOCAL lock_timeout = '3s';
SET LOCAL statement_timeout = '45s';

-- Take an immutable view of protected schema and row digests within this transaction.
CREATE TEMP TABLE cleanup_protected_schema_before ON COMMIT DROP AS
with rels as(select c.* from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','employee_presence_private','farmplast_zkt_private','auth','storage') and not(n.nspname='public' and c.relname in('assets','devices','points','alarms','device_commands','asset_points_latest','telemetry_latest','telemetry_latest_import','v_asset_points_latest','v_nj_monitoring_overview','alarms_id_seq','asset_points_latest_id_seq') or n.nspname='public' and c.relkind='i' and exists(select 1 from pg_index i join pg_class t on t.oid=i.indrelid where i.indexrelid=c.oid and t.relname in('assets','devices','points','alarms','device_commands','asset_points_latest','telemetry_latest','telemetry_latest_import','v_asset_points_latest','v_nj_monitoring_overview')))), items as(
select 'relation' as kind,c.oid::regclass::text as name,jsonb_build_array(c.relkind,c.relowner,c.relacl,c.relrowsecurity,c.relforcerowsecurity,c.reloptions)::text as definition from rels c
union all select 'column',a.attrelid::regclass::text||'.'||a.attname,jsonb_build_array(a.attnum,a.atttypid,a.atttypmod,a.attnotnull,a.attidentity,a.attgenerated,pg_get_expr(ad.adbin,ad.adrelid))::text from pg_attribute a join rels c on c.oid=a.attrelid left join pg_attrdef ad on ad.adrelid=a.attrelid and ad.adnum=a.attnum where a.attnum>0 and not a.attisdropped
union all select 'constraint',conrelid::regclass::text||'.'||conname,pg_get_constraintdef(oid) from pg_constraint where conrelid in(select oid from rels)
union all select 'index',indexrelid::regclass::text,pg_get_indexdef(indexrelid) from pg_index where indrelid in(select oid from rels)
union all select 'trigger',t.tgrelid::regclass::text||'.'||t.tgname,pg_get_triggerdef(t.oid)||t.tgenabled::text from pg_trigger t where not t.tgisinternal and t.tgrelid in(select oid from rels)
union all select 'policy',p.schemaname||'.'||p.tablename||'.'||p.policyname,to_jsonb(p)::text from pg_policies p where p.schemaname in('public','employee_presence_private','farmplast_zkt_private','auth','storage') and not(p.schemaname='public' and p.tablename in('assets','devices','points','alarms','device_commands','asset_points_latest','telemetry_latest','telemetry_latest_import','v_asset_points_latest','v_nj_monitoring_overview'))
union all select 'view',c.oid::regclass::text,pg_get_viewdef(c.oid) from rels c where c.relkind in('v','m')
union all select 'function',p.oid::regprocedure::text,pg_get_functiondef(p.oid)||coalesce(p.proacl::text,'')||p.proowner::text from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','employee_presence_private','farmplast_zkt_private','auth','storage') and p.prokind='f' and not(n.nspname='public' and p.proname in('cleanup_1day','cleanup_old_telemetry','ingest_device_points_batch','ingest_point_telemetry','set_updated_at','skip_retired_barrel_latest','sync_telemetry_history_to_latest','touch_device_heartbeat','upsert_asset_point_latest'))
union all select 'cron',jobid::text,to_jsonb(j)::text from cron.job j
union all select 'publication',pubname||'.'||schemaname||'.'||tablename,to_jsonb(p)::text from pg_publication_tables p where not(p.schemaname='public' and p.tablename in('assets','devices','points','alarms','device_commands','asset_points_latest','telemetry_latest','telemetry_latest_import','v_asset_points_latest','v_nj_monitoring_overview'))
) select count(*)::bigint as objects,md5(string_agg(kind||':'||name||':'||definition,E'\n' order by kind,name,definition)) as digest from items;
DO $guard$
BEGIN
  IF (SELECT digest FROM cleanup_protected_schema_before) <> '2e3020b6ff096fcfb42395c5d953ac2e' THEN
    RAISE EXCEPTION 'Protected schema changed since audit; abort cleanup';
  END IF;
END
$guard$;
