-- Block legacy producers and abort rather than erase unexpected data.
LOCK TABLE public.alarms, public.asset_points_latest, public.assets,
  public.device_commands, public.devices, public.points,
  public.telemetry_latest, public.telemetry_latest_import IN ACCESS EXCLUSIVE MODE;
DO $guard$
BEGIN
  IF EXISTS (SELECT 1 FROM public.alarms)
    OR EXISTS (SELECT 1 FROM public.asset_points_latest)
    OR EXISTS (SELECT 1 FROM public.device_commands)
    OR EXISTS (SELECT 1 FROM public.telemetry_latest)
    OR EXISTS (SELECT 1 FROM public.telemetry_latest_import) THEN
    RAISE EXCEPTION 'Retired telemetry or command table is no longer empty';
  END IF;
  IF (SELECT count(*) FROM public.assets) <> 2
    OR EXISTS(SELECT 1 FROM public.assets WHERE asset_code NOT IN('BARREL-NJ-01','BARREL-NJ-02'))
    OR (SELECT count(*) FROM public.devices) <> 2
    OR EXISTS(SELECT 1 FROM public.devices WHERE device_code NOT IN('ESP32-BARREL1','ESP32-BARREL2'))
    OR (SELECT count(*) FROM public.points) <> 14
    OR EXISTS(SELECT 1 FROM public.points p LEFT JOIN public.assets a ON a.id=p.asset_id
      LEFT JOIN public.devices d ON d.id=p.device_id WHERE a.id IS NULL OR d.id IS NULL
      OR d.asset_id<>a.id) THEN
    RAISE EXCEPTION 'Retired barrel catalog changed since audit';
  END IF;
END
$guard$;

