DO $guard$
BEGIN
  IF EXISTS(SELECT * FROM cleanup_protected_schema_before EXCEPT SELECT * FROM cleanup_protected_schema_after)
    OR EXISTS(SELECT * FROM cleanup_protected_schema_after EXCEPT SELECT * FROM cleanup_protected_schema_before)
    OR EXISTS(SELECT * FROM cleanup_protected_rows_before EXCEPT SELECT * FROM cleanup_protected_rows_after)
    OR EXISTS(SELECT * FROM cleanup_protected_rows_after EXCEPT SELECT * FROM cleanup_protected_rows_before) THEN
    RAISE EXCEPTION 'Protected Payroll/HR/Auth/ZKT schema or data changed; rollback required';
  END IF;
END
$guard$;
COMMIT;

